const JSON_HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const reply=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{...JSON_HEADERS,...extra}});
class HttpError extends Error{constructor(status,message){super(message);this.status=status}}
const fail=(status,message)=>{throw new HttpError(status,message)};
const string=(v,max=200)=>typeof v==='string'?v.trim().slice(0,max):'';
export function normalizeDomain(v){let name=string(v,300).toLowerCase();if(!name||/[\s/@:#?\\]/.test(name))fail(400,'Informe somente o domínio, sem endereço de página.');try{name=new URL('https://'+name).hostname}catch{fail(400,'Domínio inválido.')}if(name.length>253||!name.includes('.')||name.split('.').some(p=>!/^([a-z0-9]|[a-z0-9][a-z0-9-]{0,61}[a-z0-9])$/.test(p))||/\.(local|internal|localhost|test|invalid|example)$/.test(name)||/^\d+(\.\d+){3}$/.test(name))fail(400,'Informe um domínio público válido.');return name}
export function normalizeIP(v){const ip=string(v,60);const a=ip.split('.');if(a.length!==4||a.some(p=>!/^\d{1,3}$/.test(p)||+p>255))fail(400,'Informe um IPv4 público válido.');const [x,y]=a.map(Number);if(x===0||x===10||x===127||x>=224||(x===169&&y===254)||(x===172&&y>=16&&y<=31)||(x===192&&y===168)||(x===100&&y>=64&&y<=127)||(x===198&&(y===18||y===19)))fail(400,'Este módulo consulta apenas endereços IPv4 públicos.');return a.map(Number).join('.')}
async function readBody(request){if((request.headers.get('content-type')||'').split(';')[0].trim()!=='application/json')fail(415,'Envie o conteúdo como application/json.');if(Number(request.headers.get('content-length')||0)>1150000)fail(413,'Registro acima do limite.');const reader=request.body?.getReader();if(!reader)fail(400,'Corpo JSON ausente.');let size=0,parts=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>1150000){await reader.cancel();fail(413,'Registro acima do limite.')}parts.push(value)}const raw=new Uint8Array(size);let offset=0;for(const part of parts){raw.set(part,offset);offset+=part.length}try{const data=JSON.parse(new TextDecoder().decode(raw));if(!data||typeof data!=='object'||Array.isArray(data))fail(400,'JSON inválido.');return data}catch(e){if(e instanceof HttpError)throw e;fail(400,'JSON inválido.')}}
async function upstream(url,options={}){const r=await fetch(url,{...options,redirect:'follow',headers:{'accept':'application/json','user-agent':'NEXO-Research/1.0',...options.headers},signal:AbortSignal.timeout(12000)});if(!r.ok)fail(r.status===404?404:502,r.status===404?'Registro não encontrado na fonte consultada.':'Fonte indisponível (HTTP '+r.status+'). Tente novamente mais tarde.');const reader=r.body.getReader();let size=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>1200000){await reader.cancel();fail(502,'A fonte retornou uma resposta acima do limite.')}chunks.push(value)}const out=new Uint8Array(size);let offset=0;for(const part of chunks){out.set(part,offset);offset+=part.length}try{return JSON.parse(new TextDecoder().decode(out))}catch{fail(502,'A fonte não retornou dados JSON válidos.')}}
const recordsTypes={A:1,AAAA:28,MX:15,NS:2,TXT:16,CAA:257};
export async function lookupDNS(domain,type){domain=normalizeDomain(domain);if(!recordsTypes[type])fail(400,'Tipo DNS inválido.');const url='https://dns.google/resolve?name='+encodeURIComponent(domain)+'&type='+type;const raw=await upstream(url);return {kind:'dns',query:domain,type,source:url,collectedAt:new Date().toISOString(),dnsStatus:raw.Status,dnssec:!!raw.AD,records:(raw.Answer||[]).slice(0,100).map(r=>({name:r.name,type:r.type,ttl:r.TTL,value:r.data})),limitations:'DNS reflete a resposta do resolvedor no momento da consulta. Não comprova titularidade ou localização.'}}
export async function lookupRDAP(domain){domain=normalizeDomain(domain);const source='https://rdap.org/domain/'+encodeURIComponent(domain),raw=await upstream(source);return {kind:'rdap',query:domain,source,collectedAt:new Date().toISOString(),domain:raw.ldhName||raw.unicodeName,status:raw.status||[],events:(raw.events||[]).map(e=>({action:e.eventAction,date:e.eventDate})),nameservers:(raw.nameservers||[]).map(n=>n.ldhName),notices:(raw.notices||[]).flatMap(n=>n.description||[]).slice(0,20),limitations:'Dados públicos podem estar ocultos ou incompletos. O RDAP não identifica necessariamente o responsável por uma atividade.'}}
export async function lookupIP(ip){ip=normalizeIP(ip);const source='https://stat.ripe.net/data/network-info/data.json?resource='+encodeURIComponent(ip),raw=await upstream(source);return {kind:'ip',query:ip,source,collectedAt:new Date().toISOString(),prefix:raw.data?.prefix||null,asns:raw.data?.asns||[],limitations:'Prefixo e ASN indicam informações de roteamento. Não identificam uma pessoa nem a posição física do dispositivo.'}}
export function sanitizeWorkspace(body){if(!body||typeof body!=='object'||!Array.isArray(body.cases)||body.cases.length>40)fail(400,'Estrutura de casos inválida (máximo 40 casos).');const ids=new Set;const cases=body.cases.map(c=>{const id=string(c.id,80);if(!/^[a-zA-Z0-9_-]{6,80}$/.test(id)||ids.has(id))fail(400,'Identificador de caso inválido ou duplicado.');ids.add(id);const title=string(c.title,150);if(!title)fail(400,'O caso precisa de um título.');if(!Array.isArray(c.evidence)||c.evidence.length>200||!Array.isArray(c.timeline)||c.timeline.length>200||!Array.isArray(c.locations)||c.locations.length>100)fail(400,'Limite de itens do caso excedido.');return {id,title,description:string(c.description,2000),createdAt:string(c.createdAt,40),status:['aberto','em análise','encerrado'].includes(c.status)?c.status:'aberto',evidence:c.evidence.map(e=>({id:string(e.id,80),title:string(e.title,180),source:string(e.source,500),collectedAt:string(e.collectedAt,40),notes:string(e.notes,8000),hash:string(e.hash,64),kind:string(e.kind,50)})),timeline:c.timeline.map(t=>({id:string(t.id,80),title:string(t.title,200),at:string(t.at,40),notes:string(t.notes,2000)})),locations:c.locations.map(p=>{const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)fail(400,'Coordenadas inválidas.');return {id:string(p.id,80),title:string(p.title,150),lat,lon,source:string(p.source,500),at:string(p.at,40),precision:string(p.precision,120)}})}});return {schema:1,cases}}
export async function vaultContext(userId){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('nexo vault v1:'+userId));return [...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('')}
export function validateEnvelope(value,context){if(!value||Object.keys(value).some(k=>!['format','version','context','kdf','cipher','ciphertext'].includes(k))||value.format!=='nexo-vault'||value.version!==1||value.context!==context)fail(400,'O salvamento exige um cofre criptografado vinculado à sua conta.');const k=value.kdf,c=value.cipher;if(!k||Object.keys(k).length!==4||k.name!=='PBKDF2'||k.hash!=='SHA-256'||k.iterations!==600000||!c||Object.keys(c).length!==2||c.name!=='AES-GCM')fail(400,'Parâmetros de criptografia incompatíveis.');const bytes=(x,max)=>{if(typeof x!=='string'||x.length>max||x.length%4||!/^[A-Za-z0-9+/]*={0,2}$/.test(x))fail(400,'Conteúdo criptográfico inválido.');try{return atob(x).length}catch{fail(400,'Conteúdo criptográfico inválido.')}};if(bytes(k.salt,24)!==16||bytes(c.iv,16)!==12||bytes(value.ciphertext,1100000)<16)fail(400,'Conteúdo criptográfico inválido.');return {format:value.format,version:1,context,kdf:{name:'PBKDF2',hash:'SHA-256',iterations:600000,salt:k.salt},cipher:{name:'AES-GCM',iv:c.iv},ciphertext:value.ciphertext}}
const limits=new Map();function throttle(id){const now=Date.now();for(const [key,v]of limits)if(v.until<now)limits.delete(key);const v=limits.get(id)||{n:0,until:now+60000};if(v.n>=30)fail(429,'Limite de 30 consultas por minuto atingido.');v.n++;limits.set(id,v)}
async function runnerRequest(env,userId,path,body){if(!env.LINUX_RUNNER_URL||!env.LINUX_RUNNER_TOKEN)fail(503,'Executor Linux não configurado. É necessário um servidor isolado e escopo definido.');let base;try{base=new URL(env.LINUX_RUNNER_URL)}catch{fail(503,'URL do executor inválida.')}if(base.protocol!=='https:'||base.username||base.password||base.search||base.hash||base.pathname!=='/')fail(503,'O executor deve usar uma origem HTTPS, sem caminho ou credenciais na URL.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(userId)),owner=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');const r=await fetch(base.origin+path,{method:body?'POST':'GET',redirect:'error',headers:{'Authorization':'Bearer '+env.LINUX_RUNNER_TOKEN,'X-Nexo-User':owner,'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});let data;try{data=await r.json()}catch{fail(502,'O executor não retornou JSON.')}if(!r.ok)fail([400,403,404,429].includes(r.status)?r.status:502,string(data.error,300)||'Falha no executor.');return data}
