if(url.pathname==='/api/workspace'){if(!env.BUCKET)fail(503,'Armazenamento ainda não disponível. Exporte um backup antes de sair.');if(request.method==='GET'){const obj=await env.BUCKET.get(key);if(!obj)return reply({encrypted:false,workspace:{schema:1,cases:[],audit:[]},etag:null});const data=await obj.json();if(data.format==='nexo-storage-v2')return reply({encrypted:true,envelope:data.envelope,updatedAt:data.updatedAt,audit:data.audit,etag:obj.etag});return reply({encrypted:false,legacy:true,workspace:data,etag:obj.etag})}if(request.method==='PUT'){const expected=request.headers.get('if-match');if(!expected)fail(428,'Versão do registro ausente. Recarregue os casos.');const raw=await readBody(request);if(Object.keys(raw).length!==1||!raw.envelope)fail(400,'Dados em texto aberto não são aceitos. Criptografe o cofre no navegador.');const envelope=validateEnvelope(raw.envelope,await vaultContext(userId));let audit=[];if(expected!=='new'){const old=await env.BUCKET.get(key);if(!old||old.etag!==expected)fail(409,'O cofre mudou em outra aba. Exporte um backup e recarregue antes de salvar.');try{const previous=await old.json();audit=(previous.audit||[]).map(e=>({at:string(e.at,40),action:'vault.saved'}))}catch{}}const updatedAt=new Date().toISOString(),data={format:'nexo-storage-v2',envelope,updatedAt,audit:[...audit.slice(-99),{at:updatedAt,action:'vault.saved'}]};const result=await env.BUCKET.put(key,JSON.stringify(data),{onlyIf:expected==='new'?{etagDoesNotMatch:'*'}:{etagMatches:expected},httpMetadata:{contentType:'application/json'}});if(!result)fail(409,'Conflito de versão. Exporte o backup e recarregue.');return reply({encrypted:true,updatedAt,audit:data.audit,etag:result.etag})}fail(405,'Método não permitido.')}
if(url.pathname==='/api/osint'&&request.method==='POST'){throttle(userId);const b=await readBody(request);if(b.kind==='dns')return reply(await lookupDNS(b.query,b.type||'A'));if(b.kind==='rdap')return reply(await lookupRDAP(b.query));if(b.kind==='ip')return reply(await lookupIP(b.query));fail(400,'Módulo não disponível.')}
if(url.pathname==='/api/runner'&&request.method==='GET'){const job=url.searchParams.get('job');if(job&&!/^[a-f0-9-]{36}$/.test(job))fail(400,'Identificador de trabalho inválido.');return reply(await runnerRequest(env,userId,job?'/v1/jobs/'+job:'/v1/health'))}
